      hooks: {onError: async (_session, error) => void (hookError = error)},
    });

    const rejection = await orchestrator.processMessage(session).catch((error: unknown) => error);

    expect({rejection, hookError, message: hookError?.message, cause: hookError?.cause}).toEqual({
